// Helper functions for removing empty/nulls from json - This function is used with deep equal comp as API does not return null keys
JSON.cleanObject = obj =>
  _.transform(obj, (acc, v, k) => {
    const val = _.isObject(v) ? cleanObject(v) : v // if current value is an object clean it

    if(_.isEmpty(val)) return // ignore null, undefined, or empty objects / arrays

    acc[k] = val // assign to key
  })

function isObject(v) {
    return '[object Object]' === Object.prototype.toString.call(v);
};

// Helper functions for sorting deep json for comparison - This function is used with deep equal comp as order of list fails comparison
JSON.sort = function(o) {
if (Array.isArray(o)) {
        return o.sort().map(JSON.sort);
    } else if (isObject(o)) {
        return Object
            .keys(o)
        .sort()
            .reduce(function(a, k) {
                a[k] = JSON.sort(o[k]);

                return a;
            }, {});
    }

    return o;
}

pm.test("Response matches posted body", () => {
    const jsonData = JSON.sort(pm.response.json());
    const postRequestBody = JSON.sort(JSON.parse(pm.collectionVariables.get("POST_BODY")));
    delete jsonData["subscriptionID"];
    const isEqual = _.isEqual(jsonData, postRequestBody);
    pm.expect(isEqual).to.be.true;
});
pm.test("cleanObject drops empty values", () => {
    pm.expect(JSON.cleanObject({ a: "x", b: "", c: null })).to.eql({ a: "x" });
});
